      // key joins this flight, and synchronous mutations inside load detach it.
      flight.promise = Promise.resolve().then(work).then(
        value => {
          if (isCurrent(key, flight)) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          // Rejections are never cached; allow the next reader to retry.
          if (isCurrent(key, flight)) pending.delete(key);
          throw reason;
        }
      );
      pending.set(key, flight);
      return flight.promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

