const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // set during pending load: set wins, TTL not restarted by old commit
  {
    let t = 0; const gates = []; let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load() { calls++; const d = deferred(); gates.push(d); return d.promise; } });
    const old = c.get('k'); await tick();
    c.set('k', 'S');
    t = 5; gates[0].resolve('old'); assert.equal(await old, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; const p = c.get('k'); await tick(); assert.equal(calls, 2, 'expired set value starts new load');
    gates[1].resolve('new'); assert.equal(await p, 'new');
  }
  // repeated invalidations without stored value; old flight cannot detach newer
  {
    const gates = []; const c = createCache({ now: () => 0, load() { const d = deferred(); gates.push(d); return d.promise; } });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick(); c.invalidate('k');
    const d = c.get('k'); await tick();
    const d2 = c.get('k');
    assert.equal(gates.length, 3);
    gates[0].resolve(1); gates[1].resolve(2); await a; await b;
    const d3 = c.get('k'); await tick(); assert.equal(gates.length, 3, 'newest flight still joinable');
    gates[2].resolve(3);
    assert.deepEqual([await d, await d2, await d3], [3, 3, 3]);
    assert.equal(await c.get('k'), 3);
  }
