  {
    let n = 0; const c = createCache({ now: () => 0, load() { n++; if (n === 1) throw 'boom'; if (n === 2) return Promise.reject(null); return 'ok'; } });
    const [r1, r2] = [c.get('k'), c.get('k')];
    await assert.rejects(r1, x => x === 'boom'); await assert.rejects(r2, x => x === 'boom');
    await assert.rejects(c.get('k'), x => x === null);
    assert.equal(await c.get('k'), 'ok'); assert.equal(n, 3);
  }
  // stale rejection doesn't remove newer flight
  {
    const gates = []; const c = createCache({ now: () => 0, load() { const d = deferred(); gates.push(d); return d.promise; } });
    const a = c.get('k'); await tick(); c.clear();
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(a);
    const b2 = c.get('k'); await tick(); assert.equal(gates.length, 2);
    gates[1].resolve('v'); assert.equal(await b, 'v'); assert.equal(await b2, 'v');
  }
  // load mutating synchronously and reading own key
  {
    let n = 0; let c;
    c = createCache({ now: () => 0, load(k) { n++; if (n === 1) { c.invalidate(k); return 'first'; } return 'second'; } });
    assert.equal(await c.get('k'), 'first'); assert.equal(await c.get('k'), 'second'); assert.equal(n, 2);
    let m = 0; let inner; const c2 = createCache({ now: () => 0, load(k) { m++; inner = c2.get(k); return 'v'; } });
    assert.equal(await c2.get('k'), 'v'); assert.equal(await inner, 'v'); assert.equal(m, 1);
    let s = 0; const c3 = createCache({ now: () => 0, load(k) { s++; c3.set(k, 'SET'); return 'loaded'; } });
    assert.equal(await c3.get('k'), 'loaded'); assert.equal(await c3.get('k'), 'SET'); assert.equal(s, 1);
  }
  // ttl 0 and size
  {
    let n = 0; const g = deferred(); const c = createCache({ now: () => 0, ttlMs: 0, load() { n++; return n === 1 ? g.promise : n; } });
    const a = c.get('k'), b = c.get('k'); await tick(); g.resolve('x');
    assert.equal(await a, 'x'); assert.equal(await b, 'x'); assert.equal(n, 1);
    assert.equal(c.size, 0); assert.equal(await c.get('k'), 2);
  }
  console.log('all scenarios ok');
