'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
//
// Every flight is identified by its own record. When it settles it may only
// touch the registry (or commit its value) if it is still the registered flight
// for its key; once forget/clear (or a newer flight) has replaced it, it is
// obsolete and must neither store a value nor detach its successor.
function createFlights() {
  const pending = new Map();

  function isCurrent(key, flight) {
    return pending.get(key) === flight;
  }

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key).promise;
      const flight = {};
      // Register before work runs so a load that synchronously reads its own
      // key joins this flight, and synchronous mutations inside load detach it.
      flight.promise = Promise.resolve().then(work).then(
        value => {
          if (isCurrent(key, flight)) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          // Rejections are never cached; allow the next reader to retry.
          if (isCurrent(key, flight)) pending.delete(key);
          throw reason;
        }
      );
      pending.set(key, flight);
      return flight.promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

